GimCorpus.put(414,0,[[1,14,"אבל אם כתב וכו'. א\"א מכלל דכתב סופר ועד אחד אינו פוסל לכהונה וזה אינו כלום. אפשר דלשמואל אם נשאת הולד כשר ולדעת רב אפי' ריח גט אין בו אין השכל מורה כן, עכ\"ל:",1,0],[1,18,"הרחיק את העדים וכו'. כתב הראב\"ד ז\"ל חוכך אני בזה להחמיר שמא תתן תנאי בגט באותן שני שטין ותוציא גט בעדי חתימה ונמצא זה כמזוייף מתוכו דאתי למסמך על עדי חתימה עכ\"ל:",1,0],[1,25,"גט שיש עליו עדים וכו'. כתב הראב\"ד ז\"ל טעה במאוחר דכשר להנשא בו ולא תימא לזמן הגט אלא מדקיימא בבית דין בגיטה או שנתנו לה בעדים ולא הזכיר לה איחור זמן מותרת להנשא מיד לפי שאינו יכול לקלקלה. ואומר אני שאוכל את פירותיה עד אותו זמן ואינה גובה כתובתה עד אותו זמן שלכך איחרו וכמי שהתנה עמה הוא. וכל הפוסל גט מאוחר מפריז ומפסיד ותועה דאי היה פסול עד שהשיב רבי את ר' חנינא ב\"ג משטר מאוחר ומתרץ קסבר אין כותבין שובר ישיב עליו מגט שאינו יכול לתרץ אלא ש\"מ לדברי הכל כשר. ואני הוא המזכה ומזכה אני במקומי שאם היה פסול לא לשתמיט תנא וליתנייה ולימא ובגיטין בין מוקדם בין מאוחר פסול כדקא מפליג בפרוזבול, עכ\"ל:",1,0],[1,26,"חתך ממנו הזמן כו'. כתב הראב\"ד ז\"ל חתך ממנו הזמן ונתנו לה לכתחלה לא תנשא שהרי משלשה גיטין פסולין הוא זה, עכ\"ל:",1,0],[2,5,"וצריך שיאמר הבעל וכו'. כתב הראב\"ד ז\"ל בגמרא שלנו הרי הגט בטל עד שיאמר לסופר וכו' פרק קורדיקוס, עכ\"ל:",1,0],[2,13,"ספק הפיל עצמו וכו'. כתב הראב\"ד ז\"ל זה הספק בירושלמי מצא אותו ושם אמרו אם על אתר נפל ה\"ז גט אם לאחר שעה אין זה גט, עכ\"ל:",1,0],[3,6,"אמר לסופר כתוב וכו' לארוסתי. כתב הראב\"ד ז\"ל דוקא שזמן הגט אחר הנישואין אבל אם כתב זמן גט מן האירוסין אינו גט משום דהוי גיטה קודם לבנה עכ\"ל:",1,0],[3,10,"הואיל ועבר אדם שם וכו'. כתב הראב\"ד ז\"ל בלבול אני רואה כאן, למעלה אמר שאם לא שהה אדם שם זהו מיד וכאן הוא אומר שאם עבר אע\"פ שלא שהה חוששים ואם יאמר מפני שהוחזקו שני יוסף בן שמעון לא מצינו בגמרא הפרש כשמצאו לאלתר בין שיירות מצויות לשאינן מצויות ובין הוחזקו לשלא הוחזקו שהכל כשר ולא חלקו בהן אלא כשמצאו לאחר זמן והוחזקו שני יוסף בן שמעון בעיר אחת ר\"ל באותה העיר הכתובה בגט יוסף בן שמעון דממתא פלונית וכמדומה לי שלא כיון לזה הפירוש, עכ\"ל:",1,0],[3,11,"היה לעדים וכו'. כתב הראב\"ד ז\"ל ואפילו לשליח עכ\"ל:",1,0],[3,13,"ואם כתב כו'. כתב הראב\"ד ז\"ל נראה לי והוא שיהא רגיל באותה חניכה יותר, עכ\"ל:",1,0],[4,8,"אחד מן העדים וכו'. כתב הראב\"ד ז\"ל דבר זה מצאו בתוספתא ולא כמ\"ש אלא כך אמרו גט שכתבו בה' לשונות וחתמו עליו ה' עדים בה' לשונות פסול אבל אם חתמו עליו באחת מן הלשונות לא שמענו ואפשר שהחתימה מצרפן, עכ\"ל:",1,0],[4,14,"הרי שכתב וכו'. כתב הראב\"ד ז\"ל כתב גאון כל אלו הדקדוקים כשהבעל עומד ומערער, עכ\"ל:",1,0],[4,15,"וכן גט שנמצא קרוע וכו'. כתב הראב\"ד ז\"ל אם גט מקוים הוא למה יפסל מהיותה מגורשת שלא אמרו פסול אלא שלא תגבה בו אומרין שכבר גבתה בו וקרעוהו ב\"ד, ודומה לי שלא הסכים יפה להלכה עכ\"ל:",1,0],[5,7,"כיצד ב' קופות וכו'. כתב הראב\"ד ז\"ל זה אינו כלום דגמרא על שולים דחיצונה קא קפיד ומוטה על צדה אין לה עסק בכאן, עכ\"ל:",1,0],[5,11,"שאף על פי שדיורין כו'. כתב הראב\"ד ז\"ל לא ידעתי מהו זה ואנו לענין השאלת מקום הגט אנו מפרשים שאע\"פ שאמרו חד מקום מושלי אינשי אבל תרי לא אע\"פ שהללו שני גגין הם של שני דיורין לגבי גט כגג אחד דמו, עכ\"ל:",1,0],[5,14,"כיצד הוא קרוב לו וכו'. כתב הראב\"ד ז\"ל תמה אני אחר שהסכימו בסוף שאין מתירין אותה לינשא ואם מת צריכה חליצה מכולן עד שיגיע גט לידה למה הוצרך לאלו החקירות ואולי לדעת את שאינה מגורשת כלל, עכ\"ל:",1,0],[6,7,"אבל הנשים וכו'. כתב הראב\"ד ז\"ל ואם נתקיים בחותמיו ולא הוצרך לומר בפני נכתב בפני נחתם למה אם הביאו פסול. ועוד כשסמכו עליו למה אינו גט אלא שלא תנשא עליו ע\"כ. עוד השיג עליו וכתב לא ידעתי מאין הוציא זה ועבד ועכו\"ם הוא דקא פסיל בגמרא לפי שאינו בתורת גיטין וקדושין. אבל מי שחלל שבת או בא על אשת איש למה יהיה פסול להביא את הגט והלא הוא ישראל גמור לכל דבריו עכ\"ל:",1,0],[6,9,"וקטנה אינה עושה שליח וכו'. כתב הראב\"ד ז\"ל זה הטעם אין לו לא טעם ולא ריח אלא אתם גם אתם לרבות שלוחכם ומה אתם בני דעת אף שלוחכם בני דעת נמצא שהשליח והשולח צריכין להיות בני דעת, עכ\"ל:",1,0],[6,14,"לפיכך אם נתנו השליח וכו'. כתב הראב\"ד ז\"ל דברים בגו שאם הביאו השליח ממקום שצ\"ל בפני נכתב ובפני נחתם הרי אותן השנים כב\"ד של קיום שאינן צריכין לקרותו והשליח כב' עדים שמעידים על החתימות ועל עיקר הגט, עכ\"ל:",1,0],[6,18,"שלח הגט ביד שנים וכו'. כתב הראב\"ד ז\"ל הא (לא) מיחוורא שהרי קי\"ל כרבי דאמר עדות שבטלה מקצתה לא בטלה כולה ואימור שליחות נמי להאי הוא דבטיל לאחריני לא בטיל, עכ\"ל:",1,0],[7,11,"צריך שיאמר בפני נכתב וכו'. כתב הראב\"ד ז\"ל (בירושלמי) ואפי' נתנו בארץ, עכ\"ל:",1,0],[8,13,"הרי זה גיטך וכו'. כתב הראב\"ד ז\"ל ולמה בטל הגט והלא יכול להתקיים התנאי יגרש אותה וישא אותה בעל התנאי ויתקיים הגט למפרע ואין הולד ממזר והכי איתא בירושלמי. מכל מקום אסורה לחזור לאותה שנשאה ראשון מפני שמחזיר גרושתו מן הנשואין, עכ\"ל:",1,0],[8,21,"חזר ואמר וכו'. כתב הראב\"ד ז\"ל לא ידעתי מאין לו זה אלא מסברא דנפשיה כיון שאמר מחולין לך ומת תו לא אמרי' לצעורה קא מכוין, עכ\"ל:",1,0],[8,24,"צריכה גט משני וכו'. כתב הראב\"ד ז\"ל כמדומה לי שהוא מדמה זה הענין לאשה שהלך בעלה למדינת הים ואמרו לה מת בעלך שאם נתקדשה לאחר מותרת לחזור לו ואם נשאת אסורה לחזור לו ואין הנדון דומה לראיה כלל דלעולם אסורה לראשון דמאן מוכח שלא נתקיים התנאי שהרי בידה לקיימו והיא מגורשת גמורה ואסורה לראשון, על כן אני אומר כל מקום שתמצא כן שהתנאי בידה לקיימו אם נתקדשה לאחר צריכה גט ואסורה לראשון אבל אינו גט ליורשה וליטמא לה ולאסרה לזר בלא חליצה ולהתחייב עליה מיתת ב\"ד בהתראה, עכ\"ל:",1,0],[9,9,"וכן האומר לאשה וכו'. כתב הראב\"ד ז\"ל חיי ראשי איני יודע מחילה זו מה היא ומה יש בידה למחול בתנאים והפיוס אינו אלא שנתפייס עמה שלא לגרשה ובטל הגט שבידה ואע\"פ שאמרו משהגיע הגט לידה אינו יכול לבטלו ה\"מ בלא תנאי אבל בתנאי כל זמן שלא נתקיים התנאי יכול לבטלו, עכ\"ל:",1,0],[9,11,"הרי זה גיטך מעכשיו וכו'. כתב הראב\"ד ז\"ל זה אינו כלום דהכי נמי בעינן שתהא נאמנת עליו לומר שלא בא עכ\"ל:",1,0],[9,12,"בריא שהתנה וכו'. כתב הראב\"ד ז\"ל גם זה אינו כלום דקיי\"ל כרבי יוסי דאמר חולצת ולא מתייבמת אף בלאחר מיתה, עכ\"ל:",1,0],[9,27,"כלכם חתומו וכו'. כתב הראב\"ד ז\"ל נ\"ל שיש כאן שבוש ואולי יאמר שאר שטרות אם יאמר לעדים רבים כלכם חתומו אפילו אחד מהם פסול הכל בטל שאין אומר בשאר עדיות שהשאר משום תנאי שאין זה דומה למילאהו בקרובין הואיל וזימן את כולם לעדות ויש לזה פנים, עכ\"ל:",1,0],[10,1,"וזהו ריח הגט וכו'. כתב הראב\"ד ז\"ל לא הכל שוין בדבר זה שיש מקומות הרבה שאין מוכיח לפסלות הגט ויאמרו גרושה הותרה לכהן וכן אם קדשה אחר באותו הגט צריכה גט משני ואסורה לשניהם, עכ\"ל:",1,0],[10,19,"עד שיודע בודאי וכו'. כתב הראב\"ד ז\"ל בכותית ודאי הוא כדבריו שהרי אין בידו לגיירה אבל בשפחתו שיש בידו לשחררה דבריהם קרובים ולא שביק היתרא ואכיל איסורא אלא א\"כ הוחזק בפריצות עריות, העמד בני ישראל ובנות ישראל על חזקתן ובחזקת כשרות הן שלא יתפרצו בפני עדים לזנות ודברי הגאונים ז\"ל קיימים הם עכ\"ל:",1,0],[10,20,"הקול אסרה והקול התירה וכו'. כתב הראב\"ד ז\"ל לא נראה כן בגמרא אלא כשיצאו ב' קולות יחד מפני שהוא קול ושוברו עמו:",1,0],[10,23,"ואינו חייב לרפאותה וכו'. כתב ראב\"ד ז\"ל ואם בת רפואה היא למה לא יהא חייב לרפאותה וכמה יש שמשתטות מחמת חולי וחוזרות ומתרפאות, עכ\"ל:",1,0],[10,23,"הרי זו מגורשת וכו'. כתב הראב\"ד ז\"ל והוא שיודעת לשמור גיטה, עכ\"ל:",2,0],[11,7,"ויתירה על בת עשר וכו'. כתב הראב\"ד ז\"ל כבר כתבתי בהלכות קדושין מה שאני סובר בזה ולעולם סכלה שאינה יודעת לשמור גיטה וקדושיה אינה יכולה להתגרש אפילו היא בת י' וי\"א ולא נתנו שיעור לפעוטות אלא במתקדשת ע\"י עצמה והיא יודעת לשמור את קידושיה ואם אינה בת י' אינה מתקדשת אלא ע\"י אמה ואחיה ומדעתה ואע\"פ שיודעת לשמור קדושיה, עכ\"ל:",1,0],[11,15,"מותרת לחזור לבעלה הפקח. כתב הראב\"ד ז\"ל לא מצאתי כן בירושלמי אלא שאמר שאני קורא בה לא יוכל בעלה הראשון אשר שלחה לשוב לקחתה וכ\"נ לפי מה שאמרו בחרש שגירש, עכ\"ל:",1,0],[11,24,"אירס וברח וכו'. כתב הראב\"ד ז\"ל מנדין אותו עד שיגרש שאם אתה אומר עד שיפרוש למה ליה למימר ערוקיה מסתייה וכי לא עריק ופריש ה\"נ מסתייה אלא ש\"מ צריך לפרוש ואי עריק לא כייפינן ליה לגרש ודוקא קידש אבל כנס לא סגי בלא גירושין. ונ\"ל שמפרישין אותם אחר תשעים כימים שעמד עמה בתוך תשעים דאל\"כ מה הפסיד כשבעל באיסור ומתני' בבא על יבמתו בתוך שלשה חדשים אם אין הולד של קיימא יקיים ולא קתני יוציא התם מפני שהיא יבמה ואם יתן לה גט נאסרה עליו, עכ\"ל:",1,0],[12,2,"הוציאה גט מתחת ידה וכו'. כתב הראב\"ד ז\"ל אומר אני שיתקיים בחותמיו אע\"פ שלא יצא עליו ערער, עכ\"ל:",1,0],[12,9,"ואם נשאת תצא. כתב הראב\"ד ז\"ל ובקידושין כה\"ג אם נשאת לא תצא, עכ\"ל:",1,0],[13,24,"אחר הוא וכו'. כתב הראב\"ד ז\"ל והוא שלא הוחזקו שנים, עכ\"ל:",1,0],[13,29,"בנות ישראל עגונות: כתב הראב\"ד ז\"ל אי נמי דאיהי דייקא ומינסבא, עכ\"ל:",1,0]]);
